INSERT INTO events (organizer_id, title, slug, description, event_type, venue, city, state, event_date, flag_off_time, registration_open, registration_close, status, rejection_reason, created_at) VALUES (1, 'Penang Bridge International Marathon 2027', 'penang-bridge-marathon-2027', 'Run across the iconic 13.5 km Penang Bridge at sunrise. A certified AIMS course with full road closure, hydration stations every 2.5 km and a finish festival at Queensbay Mall.', 'ROAD', 'Penang Bridge, Gelugor', 'George Town', 'Pulau Pinang', DATE '2027-03-14', TIME '04:00:00', DATE '2026-10-01', DATE '2027-02-15', 'APPROVED', NULL, TIMESTAMP '2026-09-10 09:00:00');
INSERT INTO events (organizer_id, title, slug, description, event_type, venue, city, state, event_date, flag_off_time, registration_open, registration_close, status, rejection_reason, created_at) VALUES (1, 'KL City Night Run 2027', 'kl-city-night-run-2027', 'Experience Kuala Lumpur after dark. A flat city-centre route passing Dataran Merdeka, KLCC and Bukit Bintang with live music at every kilometre.', 'ROAD', 'Dataran Merdeka', 'Kuala Lumpur', 'W.P. Kuala Lumpur', DATE '2027-01-23', TIME '19:30:00', DATE '2026-11-01', DATE '2027-01-10', 'APPROVED', NULL, TIMESTAMP '2026-09-10 09:00:00');
INSERT INTO events (organizer_id, title, slug, description, event_type, venue, city, state, event_date, flag_off_time, registration_open, registration_close, status, rejection_reason, created_at) VALUES (2, 'UiTM Neon Fun Run 2026', 'uitm-neon-fun-run-2026', 'The biggest student run of the semester. Glow sticks, neon paint, campus DJ and a 5KM route around UiTM Shah Alam. Open to students, staff and the public.', 'FUN_RUN', 'UiTM Shah Alam', 'Shah Alam', 'Selangor', DATE '2026-12-12', TIME '18:00:00', DATE '2026-10-15', DATE '2026-12-05', 'APPROVED', NULL, TIMESTAMP '2026-09-10 09:00:00');
INSERT INTO events (organizer_id, title, slug, description, event_type, venue, city, state, event_date, flag_off_time, registration_open, registration_close, status, rejection_reason, created_at) VALUES (1, 'Putrajaya Half Marathon 2027', 'putrajaya-half-marathon-2027', 'A scenic lakeside half marathon through the federal administrative capital. Ideal for runners chasing a personal best on a flat, fast course.', 'ROAD', 'Dataran Putrajaya, Presint 3', 'Putrajaya', 'W.P. Putrajaya', DATE '2027-05-09', TIME '05:00:00', DATE '2026-11-01', DATE '2027-04-15', 'APPROVED', NULL, TIMESTAMP '2026-09-10 09:00:00');
INSERT INTO events (organizer_id, title, slug, description, event_type, venue, city, state, event_date, flag_off_time, registration_open, registration_close, status, rejection_reason, created_at) VALUES (2, 'Sabah Highland Trail Challenge 2027', 'sabah-highland-trail-2027', 'Technical trail racing through the cool highlands of Kundasang with views of Mount Kinabalu. Mandatory kit list applies for the 30KM category.', 'TRAIL', 'Kundasang Sports Complex', 'Kundasang', 'Sabah', DATE '2027-02-06', TIME '05:30:00', DATE '2026-11-01', DATE '2027-01-20', 'PENDING', NULL, TIMESTAMP '2026-09-10 09:00:00');
INSERT INTO events (organizer_id, title, slug, description, event_type, venue, city, state, event_date, flag_off_time, registration_open, registration_close, status, rejection_reason, created_at) VALUES (2, 'Borneo Ultra 2027', 'borneo-ultra-2027', 'A 50KM ultra through the rainforest of Kubah National Park. Draft event awaiting final permits.', 'TRAIL', 'Kubah National Park', 'Kuching', 'Sarawak', DATE '2027-04-18', TIME '04:30:00', DATE '2026-12-15', DATE '2027-03-20', 'DRAFT', NULL, TIMESTAMP '2026-09-10 09:00:00');
INSERT INTO events (organizer_id, title, slug, description, event_type, venue, city, state, event_date, flag_off_time, registration_open, registration_close, status, rejection_reason, created_at) VALUES (1, 'Melaka Heritage Run 2026', 'melaka-heritage-run-2026', 'A heritage trail through the UNESCO-listed streets of Bandar Hilir, finishing at A''Famosa. Completed event with published results.', 'ROAD', 'A''Famosa, Bandar Hilir', 'Melaka', 'Melaka', DATE '2026-10-04', TIME '06:00:00', DATE '2026-07-01', DATE '2026-09-20', 'COMPLETED', NULL, TIMESTAMP '2026-09-10 09:00:00');
INSERT INTO events (organizer_id, title, slug, description, event_type, venue, city, state, event_date, flag_off_time, registration_open, registration_close, status, rejection_reason, created_at) VALUES (2, 'Langkawi Coastal Run 2027', 'langkawi-coastal-run-2027', 'Island coastal route starting at Pantai Cenang. Proposal rejected pending district council permit and traffic management plan.', 'ROAD', 'Pantai Cenang', 'Langkawi', 'Kedah', DATE '2027-03-28', TIME '06:00:00', DATE '2026-11-15', DATE '2027-02-28', 'REJECTED', 'Venue permit and traffic management plan were not attached. Please resubmit with the district council approval letter.', TIMESTAMP '2026-09-10 09:00:00');
INSERT INTO events (organizer_id, title, slug, description, event_type, venue, city, state, event_date, flag_off_time, registration_open, registration_close, status, rejection_reason, created_at) VALUES (1, 'Merdeka Virtual 65 Challenge', 'merdeka-virtual-65-2026', 'Run 6.5 km anywhere in Malaysia between 1 and 16 September 2026 to celebrate Merdeka. Finisher medals posted nationwide.', 'VIRTUAL', 'Anywhere in Malaysia', 'Nationwide', 'Malaysia', DATE '2026-09-16', TIME '00:00:00', DATE '2026-08-01', DATE '2026-09-16', 'COMPLETED', NULL, TIMESTAMP '2026-09-10 09:00:00');
