INSERT INTO announcements (event_id, title, body, audience, created_by, published_at) VALUES (3, 'Race kit collection starts 8 December', 'Collect your race kit at the UiTM Shah Alam Grand Hall from 8 to 11 December, 10:00 AM to 8:00 PM. Bring your confirmation e-mail and MyKad. Proxy collection is allowed with a signed authorisation letter.', 'ALL', 3, TIMESTAMP '2026-11-10 09:00:00');
INSERT INTO announcements (event_id, title, body, audience, created_by, published_at) VALUES (3, 'Neon paint station and bag drop', 'Bag drop opens at 4:00 PM at the start pen. Neon paint stations are free for all participants. Please wear light-coloured clothing for the best glow effect.', 'CONFIRMED', 3, TIMESTAMP '2026-11-12 15:30:00');
INSERT INTO announcements (event_id, title, body, audience, created_by, published_at) VALUES (1, 'Early bird registration extended', 'Early bird pricing for the Penang Bridge International Marathon 2027 has been extended to 30 November 2026. Register now to secure your slot and limited-edition finisher tee.', 'ALL', 2, TIMESTAMP '2026-11-08 11:00:00');
INSERT INTO announcements (event_id, title, body, audience, created_by, published_at) VALUES (7, 'Official results and e-certificates released', 'The official results for Melaka Heritage Run 2026 are now available. Log in and open My Registrations to view your finish time, pace, position and e-certificate.', 'ALL', 2, TIMESTAMP '2026-10-06 18:00:00');
INSERT INTO announcements (event_id, title, body, audience, created_by, published_at) VALUES (10, 'Pacers confirmed for December time trial', 'Pacing groups for 20, 25, 30, 35 and 40 minutes are confirmed. Arrive 30 minutes early for warm-up and bib collection.', 'ALL', 3, TIMESTAMP '2026-11-13 10:00:00');
